#include <bits/stdc++.h>
using namespace std;

void updateWordCountAndMaxLength(const string& word, bool inBraces, function<void(int)> consumer) {
    int len = (int)word.length();
    if (len > 0) {
        consumer(len);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int totalChars;
    cin >> totalChars;
    cin.ignore(); // To consume the newline after the integer input

    string inputLine;
    getline(cin, inputLine);

    int totalWordsInBraces = 0;
    int maxWordLength = 0;
    bool inBracesFlag = false;
    string currentWord;

    for (int index = 0; index < totalChars; index++) {
        char ch = inputLine[index];

        if (ch == '_') {
            updateWordCountAndMaxLength(currentWord, inBracesFlag, [&](int length) {
                if (length > 0) {
                    if (inBracesFlag) {
                        totalWordsInBraces++;
                    } else {
                        maxWordLength = max(maxWordLength, length);
                    }
                }
            });
            currentWord.clear();
        } else if (ch == '(') {
            updateWordCountAndMaxLength(currentWord, inBracesFlag, [&](int length) {
                if (length > 0) {
                    if (inBracesFlag) {
                        totalWordsInBraces++;
                    } else {
                        maxWordLength = max(maxWordLength, length);
                    }
                }
            });
            currentWord.clear();
            inBracesFlag = true;
        } else if (ch == ')') {
            updateWordCountAndMaxLength(currentWord, inBracesFlag, [&](int length) {
                if (length > 0) {
                    if (inBracesFlag) {
                        totalWordsInBraces++;
                    } else {
                        maxWordLength = max(maxWordLength, length);
                    }
                }
            });
            currentWord.clear();
            inBracesFlag = false;
        } else if (isalpha(ch)) {
            currentWord += ch;
        }
    }

    updateWordCountAndMaxLength(currentWord, inBracesFlag, [&](int length) {
        if (length > 0) {
            if (inBracesFlag) {
                totalWordsInBraces++;
            } else {
                maxWordLength = max(maxWordLength, length);
            }
        }
    });

    cout << maxWordLength << " " << totalWordsInBraces << "\n";

    return 0;
}
